window.CONCEPT_CARDS = [
  /* ── 01 Pro/Unpro Relationships ── */
  { module:`Pro/Unpro Relationships`, ref:`Professional`, q:`Describe professional relationships.`, a:`They reflect Air Force and Space Force standards of conduct and core values; enhance morale, unit cohesion, good order, discipline, and mission focus; and preserve respect for authority.` },
  { module:`Pro/Unpro Relationships`, ref:`Unprofessional`, q:`Describe unprofessional relationships (UPRs).`, a:`They detract from the authority of superiors; result in — or appear to show — favoritism, partiality, or misuse of position; and abandon organizational goals for personal interests. They can exist between officers, enlisted, and military, civilian, or contractor personnel.` },
  { module:`Pro/Unpro Relationships`, ref:`Official concern`, q:`When does a personal relationship become an official concern?`, a:`When it adversely affects morale, good order, discipline, respect for authority, unit cohesion, or the mission.` },
  { module:`Pro/Unpro Relationships`, ref:`Prohibited when`, q:`When is a relationship prohibited?`, a:`When it compromises the chain of command, creates perceptions of favoritism, involves improper use of grade for personal gain, is exploitative, or negatively impacts the mission.` },
  { module:`Pro/Unpro Relationships`, ref:`Responsibility`, q:`Who is primarily responsible for maintaining professional standards in a relationship?`, a:`All members are accountable, but the SENIOR member in the relationship is primarily responsible.` },
  { module:`Pro/Unpro Relationships`, ref:`Scope`, q:`What is the scope of the relationships policy?`, a:`It applies on or off duty, across all branches and components, and includes interactions on social media.` },
  { module:`Pro/Unpro Relationships`, ref:`General prohibition`, q:`What is the general prohibition for officers?`, a:`Officers must avoid activities with enlisted members that could prejudice good order and discipline, discredit the armed forces, or compromise the officer's standing.` },
  { module:`Pro/Unpro Relationships`, ref:`Specific prohibitions`, q:`List the five specific prohibitions — officers will not...`, a:`1) Gamble with enlisted members. 2) Lend money to or borrow money from enlisted members. 3) Share living accommodations with enlisted members. 4) Engage in business or solicit sales with enlisted members. 5) Date or engage in sexual relations with enlisted members.` },
  { module:`Pro/Unpro Relationships`, ref:`Fraternization`, q:`Define fraternization.`, a:`A UPR between an officer and an enlisted member that violates customs of acceptable behavior and prejudices good order and discipline or discredits the armed services.` },
  { module:`Pro/Unpro Relationships`, ref:`Marriage`, q:`Does a subsequent marriage excuse fraternization?`, a:`No. A subsequent marriage does not excuse prior acts of fraternization.` },
  { module:`Pro/Unpro Relationships`, ref:`Effects`, q:`Summarize the effects of UPRs on unit cohesiveness.`, a:`Erodes trust and respect (undermines a leader's integrity and creates doubt in their motives); degrades morale (perceptions of favoritism and an "in crowd"); undermines the authority of other leaders trying to maintain standards; and impacts the mission through degraded cohesion and discipline.` },
  { module:`Pro/Unpro Relationships`, ref:`Sexual relationships`, q:`Why are sexual relationships singled out?`, a:`They carry an increased potential to cause significant degradation of unit cohesion, respect for authority, discipline, and mission accomplishment.` },

  /* ── 02 Core Values ── */
  { module:`Core Values`, ref:`Virtues`, q:`What are virtues?`, a:`Desired behaviors and characteristics — qualities considered morally good or desirable. The consistent practice of virtues creates habits of honorable thought and action.` },
  { module:`Core Values`, ref:`Virtues to Values`, q:`How do virtues relate to the Core Values?`, a:`Virtues demonstrate that one truly values Integrity, Service, and Excellence. For Guardians, "Commitments" are the equivalent of virtues for the 4 Cs. They are the tangible actions and characteristics that bring the Core Values to life.` },
  { module:`Core Values`, ref:`USAF values`, q:`Name the three USAF Core Values.`, a:`Integrity First, Service Before Self, and Excellence in All We Do.` },
  { module:`Core Values`, ref:`Integrity First`, q:`Integrity First — define it and name its virtues.`, a:`The single most important part of character; doing the right thing, all the time. Virtues: Honesty, Courage, Accountability, and Humility.` },
  { module:`Core Values`, ref:`Honesty`, q:`Honesty (virtue)?`, a:`Preserves trust.` },
  { module:`Core Values`, ref:`Courage`, q:`Courage (virtue under Integrity First)?`, a:`Willingness to take risks and admit mistakes.` },
  { module:`Core Values`, ref:`Accountability`, q:`Accountability (virtue)?`, a:`Taking ownership of your actions and decisions.` },
  { module:`Core Values`, ref:`Humility`, q:`Humility (virtue)?`, a:`Service with gratitude, putting others first.` },
  { module:`Core Values`, ref:`Service Before Self`, q:`Service Before Self — define it and name its virtues.`, a:`Professional duties take precedence over personal desires. Virtues: Duty, Loyalty, and Respect.` },
  { module:`Core Values`, ref:`Duty`, q:`Duty (virtue)?`, a:`Making necessary sacrifices to accomplish the mission.` },
  { module:`Core Values`, ref:`Loyalty`, q:`Loyalty (virtue)?`, a:`Commitment to something bigger than oneself.` },
  { module:`Core Values`, ref:`Respect`, q:`Respect (virtue)?`, a:`Treating others with dignity.` },
  { module:`Core Values`, ref:`Excellence`, q:`Excellence in All We Do — define it and name its virtues.`, a:`A passion for continuous improvement and innovation. Virtues: Mission, Discipline, and Teamwork.` },
  { module:`Core Values`, ref:`Mission`, q:`Mission (virtue under Excellence)?`, a:`Focus on operations, product, and resource excellence.` },
  { module:`Core Values`, ref:`Discipline`, q:`Discipline (virtue)?`, a:`Upholding the highest personal and professional standards.` },
  { module:`Core Values`, ref:`Teamwork`, q:`Teamwork (virtue)?`, a:`Recognizing the interdependency of every member's contribution.` },
  { module:`Core Values`, ref:`The 4 Cs`, q:`Name the four USSF Core Values.`, a:`Character, Connection, Commitment, and Courage — the 4 Cs.` },
  { module:`Core Values`, ref:`USSF Character`, q:`USSF Character — value and commitments.`, a:`High moral and ethical standards; embracing integrity, grit, honesty, and trustworthiness. Commitments: act with integrity, be accountable, uphold standards.` },
  { module:`Core Values`, ref:`USSF Connection`, q:`USSF Connection — value and commitments.`, a:`Common purpose; stronger together, embracing diverse perspectives. Commitments: engage with respect, foster a fearless environment, encourage sharing, give and seek help.` },
  { module:`Core Values`, ref:`USSF Commitment`, q:`USSF Commitment — value and commitments.`, a:`Pursuit of mastery of self, profession, and domain. Commitments: achieve audacious goals, learn from experience, seek and offer feedback, embrace challenges.` },
  { module:`Core Values`, ref:`USSF Courage`, q:`USSF Courage — value and commitments.`, a:`Doing and saying what is right; a bias toward action and accepting necessary risk. Commitments: be steadfast, innovate, share ideas, take smart risks.` },
  { module:`Core Values`, ref:`Importance`, q:`Why are the Core Values important to Airmen and Guardians?`, a:`They are the bedrock of leadership in the Air and Space Forces; a moral framework and compass for all military activities; fundamental and enduring principles of conduct; the professional identity of a member of the Profession of Arms; and critical to growth and accountability.` },
  { module:`Core Values`, ref:`Guardian Spirit`, q:`What is the Guardian Spirit?`, a:`The embodiment of Character, Connection, Commitment, and Courage — essential for thriving in the Space Force.` },

  /* ── 03 US Constitution ── */
  { module:`US Constitution`, ref:`Military authority`, q:`Which branch of government establishes military authority?`, a:`The Executive Branch — derived from Article II of the Constitution, with the President as Commander in Chief.` },
  { module:`US Constitution`, ref:`Three provisions`, q:`List the three provisions embodied in the US Constitution.`, a:`Enumerated Powers, Separation of Powers, and Federalism.` },
  { module:`US Constitution`, ref:`Enumerated Powers`, q:`Provision: Enumerated Powers.`, a:`Limits the federal government to powers explicitly granted in the Constitution.` },
  { module:`US Constitution`, ref:`Separation of Powers`, q:`Provision: Separation of Powers.`, a:`Divides government into three independent branches — Legislative, Executive, and Judicial — to prevent the concentration of power.` },
  { module:`US Constitution`, ref:`Federalism`, q:`Provision: Federalism.`, a:`Divides and shares power between the national and state governments.` },
  { module:`US Constitution`, ref:`Bill of Rights`, q:`What part of the Constitution most restricts a military officer's authority?`, a:`The Bill of Rights — the first 10 Amendments.` },
  { module:`US Constitution`, ref:`1st Amendment`, q:`First Amendment — military relevance.`, a:`Limits restrictions on troops' freedom of speech and religion, though the necessities of military discipline may allow more restriction than in civilian life.` },
  { module:`US Constitution`, ref:`2nd Amendment`, q:`Second Amendment — military relevance.`, a:`Prohibits military officers from taking weapons from the public.` },
  { module:`US Constitution`, ref:`3rd Amendment`, q:`Third Amendment — military relevance.`, a:`Prohibits the military from forcing the public to house soldiers.` },
  { module:`US Constitution`, ref:`5th Amendment`, q:`Fifth Amendment — military relevance.`, a:`Contains an exception to grand jury indictment for persons serving in the armed forces, who are instead subject to the court-martial system.` },

  /* ── 04 Full Range Leadership ── */
  { module:`Full Range Leadership`, ref:`Three approaches`, q:`Name the three leadership approaches in the Full Range Leadership model.`, a:`Laissez-Faire, Transactional, and Transformational.` },
  { module:`Full Range Leadership`, ref:`Laissez-Faire`, q:`Laissez-Faire leadership — characteristics.`, a:`The "hands-off" leader. Absence of action or leadership; avoids making decisions; disconnected from the mission and fails to follow up; does not develop subordinates. An approach of non-leadership that should be avoided.` },
  { module:`Full Range Leadership`, ref:`Transactional`, q:`Transactional leadership — characteristics.`, a:`The "task-focused" leader. Focuses on exchanges between leaders and followers; seeks to maintain stability and achieve goals through a system of rewards and corrective actions. Three behaviors: Contingent Reward, MBE-Active, MBE-Passive.` },
  { module:`Full Range Leadership`, ref:`Contingent Reward`, q:`Contingent Reward (CR).`, a:`Sets expectations and provides rewards when they are met.` },
  { module:`Full Range Leadership`, ref:`MBE-Active`, q:`Management by Exception - Active (MBE-A).`, a:`Constantly monitors for deviations from standards and corrects them immediately.` },
  { module:`Full Range Leadership`, ref:`MBE-Passive`, q:`Management by Exception - Passive (MBE-P).`, a:`Waits for problems to arise before intervening.` },
  { module:`Full Range Leadership`, ref:`Transformational`, q:`Transformational leadership — characteristics.`, a:`The "people-focused" leader. Creates personal relationships to motivate and inspire followers; attentive to followers' needs and helps them reach their fullest potential. Four behaviors: Idealized Influence, Inspirational Motivation, Intellectual Stimulation, Individual Consideration.` },
  { module:`Full Range Leadership`, ref:`Idealized Influence`, q:`Idealized Influence (II).`, a:`Acts as a positive role model — "walking the talk."` },
  { module:`Full Range Leadership`, ref:`Inspirational Motivation`, q:`Inspirational Motivation (IM).`, a:`Inspires and motivates with a shared vision — "talking the talk."` },
  { module:`Full Range Leadership`, ref:`Intellectual Stimulation`, q:`Intellectual Stimulation (IS).`, a:`Stimulates creative thinking and challenges old ways of doing things.` },
  { module:`Full Range Leadership`, ref:`Individual Consideration`, q:`Individual Consideration (IC).`, a:`Acts as a coach or mentor, focusing on subordinate development.` },
  { module:`Full Range Leadership`, ref:`Applying FRL`, q:`How do you apply Full Range Leadership?`, a:`It is not a "bad to good" continuum — it represents a range of leadership activity and effectiveness, and different circumstances require different approaches. Effective leaders blend several approaches simultaneously based on the situation, and avoid laissez-faire.` },
  { module:`Full Range Leadership`, ref:`Military value`, q:`Why is FRL particularly helpful in the military?`, a:`It helps resolve issues in dynamic environments and illustrates the behaviors needed to accomplish the mission.` },

  /* ── 05 Followership ── */
  { module:`Followership`, ref:`Five styles`, q:`Name the five followership styles.`, a:`Sheep, Yes People, Survivors, Alienated Followers, and Effective Followers.` },
  { module:`Followership`, ref:`Two dimensions`, q:`What two dimensions define the followership styles?`, a:`Active versus passive, and whether the person is a critical thinker.` },
  { module:`Followership`, ref:`Sheep`, q:`Followership style: Sheep.`, a:`Passive and not a critical thinker. They wait for instructions, do only what is asked, and show no initiative.` },
  { module:`Followership`, ref:`Yes People`, q:`Followership style: Yes People.`, a:`Active but not a critical thinker. They depend on the leader for direction and will not question any orders.` },
  { module:`Followership`, ref:`Survivors`, q:`Followership style: Survivors.`, a:`A mix of all styles. They do just enough to get by and avoid making waves or taking risks.` },
  { module:`Followership`, ref:`Alienated`, q:`Followership style: Alienated Followers.`, a:`A critical thinker but passive. Often cynical — they criticize leadership but do not offer solutions.` },
  { module:`Followership`, ref:`Effective`, q:`Followership style: Effective Followers.`, a:`Active and a critical thinker. Proactive, take initiative, work well with others, and are not afraid to raise concerns with their leader.` },
  { module:`Followership`, ref:`Effective traits`, q:`Characteristics of an effective follower.`, a:`Support your boss and do not undermine them; disagree privately; take initiative to make decisions and act; accept responsibility when offered; tell the truth; do your homework and anticipate your boss's questions; know your strengths and weaknesses; keep your boss informed; fix problems without worrying about credit; and do not forget your family's needs.` },
  { module:`Followership`, ref:`Follower to leader`, q:`How do followership and leadership connect?`, a:`To be a good leader you must first be a good follower; most people are leaders and followers at the same time; developing good followers is the first step to creating good leaders; good followers often transition into leadership roles; and effective leaders and followers share many of the same skills and qualities.` },

  /* ── 06 Team Building ── */
  { module:`Team Building`, ref:`Four stages`, q:`Name the four stages of team growth in order.`, a:`Forming, Storming, Norming, Performing.` },
  { module:`Team Building`, ref:`Forming`, q:`Team stage: Forming.`, a:`Team members determine their roles and transition from individual to member status.` },
  { module:`Team Building`, ref:`Storming`, q:`Team stage: Storming.`, a:`Conflict arises as members resist collaboration and argue over team actions. This is the most difficult stage.` },
  { module:`Team Building`, ref:`Norming`, q:`Team stage: Norming.`, a:`Cohesiveness and commitment are established, conflict is reduced, and team norms are set.` },
  { module:`Team Building`, ref:`Performing`, q:`Team stage: Performing.`, a:`The team becomes proficient, solves problems, and members accept each other's strengths and weaknesses.` },
  { module:`Team Building`, ref:`Leader roles`, q:`Name the leader role at each of the four stages.`, a:`Forming = Director. Storming = Coach. Norming = Collaborator. Performing = Visionary.` },
  { module:`Team Building`, ref:`Forming leader`, q:`Leader actions in the Forming stage.`, a:`Be directive; help the team get to know one another; clearly define roles and the team's mission and tasks.` },
  { module:`Team Building`, ref:`Storming leader`, q:`Leader actions in the Storming stage.`, a:`Act as a coach to control chaos; create a climate of open discussion and listen to concerns; get input from members on how to achieve goals; be encouraging and supportive and facilitate conflict resolution.` },
  { module:`Team Building`, ref:`Norming leader`, q:`Leader actions in the Norming stage.`, a:`Act as a facilitator and collaborator; delegate responsibilities to build member confidence; maximize members' strengths and contributions.` },
  { module:`Team Building`, ref:`Performing leader`, q:`Leader actions in the Performing stage.`, a:`Act as a visionary focused on maintaining success; plan for the future and cultivate leadership talent within the team; foster new ideas and ensure solid mechanisms for feedback.` },
  { module:`Team Building`, ref:`Follower actions`, q:`Follower actions across the stages.`, a:`Storming — voice concerns and provide input on goals. Norming — establish cohesiveness and commitment, reconcile competing loyalties, and increase cooperation. Performing — embrace roles, accept each other's strengths and weaknesses, and begin solving problems and implementing change effectively.` },

  /* ── 07 Problem Solving ── */
  { module:`Problem Solving`, ref:`Definition`, q:`Define problem-solving.`, a:`The purposeful act of observing a problem, considering solutions, and deciding to solve it.` },
  { module:`Problem Solving`, ref:`OODA steps`, q:`What do the letters O-O-D-A stand for?`, a:`Observe, Orient, Decide, Act.` },
  { module:`Problem Solving`, ref:`OODA traits`, q:`OODA Loop — key characteristics.`, a:`4 steps; rapid decision-making; suited to combat and time-compressed environments; a single decision maker; a continuous cycle.` },
  { module:`Problem Solving`, ref:`PPSM traits`, q:`8-Step PPSM — key characteristics.`, a:`8 detailed steps; long-term problem solving; a team-centered approach; process-improvement focus; systematic methodology.` },
  { module:`Problem Solving`, ref:`Comparison`, q:`Compare the PPSM to the OODA Loop.`, a:`OODA is 4 steps for rapid, time-compressed decisions by a single decision maker in a continuous cycle. PPSM is 8 detailed steps for long-term, team-centered, systematic process improvement.` },
  { module:`Problem Solving`, ref:`PPSM steps`, q:`Name the 8 PPSM steps in order.`, a:`1) Clarify the Problem 2) Break Down the Problem and ID Performance Gaps 3) Set Improvement Targets 4) Determine Root Causes 5) Develop Countermeasures 6) See Countermeasures Through 7) Confirm Results and Process 8) Standardize Successful Processes.` },
  { module:`Problem Solving`, ref:`PPSM step 1`, q:`What is PPSM Step 1?`, a:`Clarify the Problem.` },
  { module:`Problem Solving`, ref:`PPSM step 3`, q:`What is PPSM Step 3?`, a:`Set Improvement Targets.` },
  { module:`Problem Solving`, ref:`PPSM step 4`, q:`Which PPSM step determines root causes?`, a:`Step 4 — Determine Root Causes.` },
  { module:`Problem Solving`, ref:`PPSM step 8`, q:`What is the final PPSM step?`, a:`Step 8 — Standardize Successful Processes.` },

  /* ── 08 Critical Thinking ── */
  { module:`Critical Thinking`, ref:`Definition`, q:`Define critical thinking.`, a:`The process of thinking carefully about a subject or idea without allowing feelings or opinions to affect you. It raises vital questions and problems, gathers and assesses relevant information, reaches well-reasoned conclusions and solutions, and remains open-minded.` },
  { module:`Critical Thinking`, ref:`Statement vs argument`, q:`Statement versus argument.`, a:`A statement can be true or false. An argument provides a reason — a premise — for a given conclusion.` },
  { module:`Critical Thinking`, ref:`Fact vs opinion`, q:`Fact versus opinion.`, a:`A fact is something true that can be proven and is objective and verifiable. An opinion is a subjective belief a person has formed that cannot be verified.` },
  { module:`Critical Thinking`, ref:`Objective vs subjective`, q:`Objective versus subjective claim.`, a:`An objective claim is factually true or false independent of what people think. A subjective claim's truth or falsity depends on what people think.` },
  { module:`Critical Thinking`, ref:`Nine standards`, q:`Name the nine intellectual standards.`, a:`Clarity, Accuracy, Precision, Relevance, Depth, Breadth, Logic, Significance, Fairness.` },
  { module:`Critical Thinking`, ref:`Standards purpose`, q:`What are the intellectual standards used for?`, a:`They are applied to thinking to verify the quality of the information being presented or received.` },
  { module:`Critical Thinking`, ref:`Clarity`, q:`Standard: Clarity.`, a:`The "gateway standard," relevant to all the others. If a statement is unclear, you cannot determine its accuracy or relevance.` },
  { module:`Critical Thinking`, ref:`Accuracy`, q:`Standard: Accuracy.`, a:`Addresses the validity and truthfulness of the information.` },
  { module:`Critical Thinking`, ref:`Precision`, q:`Standard: Precision.`, a:`Helps refine information by adding necessary details.` },
  { module:`Critical Thinking`, ref:`Relevance`, q:`Standard: Relevance.`, a:`Evaluates what is most related to the issue at hand.` },
  { module:`Critical Thinking`, ref:`Depth`, q:`Standard: Depth.`, a:`Addresses the complexities and deeper layers of an issue.` },
  { module:`Critical Thinking`, ref:`Breadth`, q:`Standard: Breadth.`, a:`Addresses various interpretations and other points of view.` },
  { module:`Critical Thinking`, ref:`Logic`, q:`Standard: Logic.`, a:`Ensures that thoughts are mutually supporting and make sense in combination.` },
  { module:`Critical Thinking`, ref:`Significance`, q:`Standard: Significance.`, a:`Identifies the most important pieces of an argument or issue.` },
  { module:`Critical Thinking`, ref:`Fairness`, q:`Standard: Fairness.`, a:`Acts as a "gut check" to avoid personal interests, ego, and unjustified assumptions.` },
  { module:`Critical Thinking`, ref:`Cognitive ops`, q:`What are cognitive domain operations?`, a:`Operations that aim to influence an adversary's will, beliefs, and thinking in order to affect their decisions and actions. They target the human brain as the main combat space and exploit psychological weaknesses such as fear, anxiety, and suspicion to weaken the will to fight.` },
  { module:`Critical Thinking`, ref:`Cognitive ops goal`, q:`What does a cognitive domain operation try to make an opponent feel?`, a:`"I can't," then "I dare not," and ultimately "I don't want to."` },
  { module:`Critical Thinking`, ref:`Cognitive ops scope`, q:`When and where do cognitive domain operations occur?`, a:`Constantly — in peace and war, across political, economic, and social fields. Information is the primary ammunition, and social media is a main battleground.` },
  { module:`Critical Thinking`, ref:`Disinformation`, q:`How does disinformation relate to cognitive domain operations?`, a:`Disinformation is a key tool. Operations use cognitive interference, confusion, and information blocking to cause misjudgment; social media, AI, and deep fakes spread it; and it exploits confirmation bias, where people favor information that confirms their existing beliefs.` },
  { module:`Critical Thinking`, ref:`Three Powers`, q:`What are the "Three Powers" cognitive operations seek to control?`, a:`Defining an event, dominating its process, and judging its outcome — often through spreading false or misleading information.` },
  { module:`Critical Thinking`, ref:`Elements list`, q:`Name the eight elements of reasoning.`, a:`Purpose, Question at Issue, Points of View, Information, Concepts, Assumptions, Inferences, and Implications and Consequences.` },
  { module:`Critical Thinking`, ref:`Elements 1-4`, q:`Define: Purpose, Question at Issue, Points of View, Information.`, a:`Purpose — the objective or goal of your thinking. Question at Issue — the central problem or question that needs to be answered. Points of View — the different perspectives from which to see the issue. Information — the data, facts, and evidence used to support reasoning.` },
  { module:`Critical Thinking`, ref:`Elements 5-8`, q:`Define: Concepts, Assumptions, Inferences, Implications and Consequences.`, a:`Concepts — the theories, principles, and ideas that frame the thinking. Assumptions — beliefs and values taken for granted. Inferences — the conclusions drawn from information and assumptions. Implications and Consequences — the potential outcomes of a decision or action.` },
  { module:`Critical Thinking`, ref:`System 1`, q:`Thinking error: relying on System 1 thinking.`, a:`Using fast, instinctive, and emotional thinking instead of slow, deliberate, and logical System 2 thinking.` },
  { module:`Critical Thinking`, ref:`Wrong questions`, q:`Thinking errors: wrong questions, thinking too quickly, stereotypes.`, a:`Asking the Wrong Questions — failing to identify the correct problem or asking in a way that does not lead to understanding. Thinking Too Quickly — rushing to judgment without sufficient analysis. Stereotypes — snap judgments and oversimplifications that prohibit critical thought.` },
  { module:`Critical Thinking`, ref:`Halo Effect`, q:`Cognitive bias: Halo Effect.`, a:`Allowing a single trait to define a whole person or situation.` },
  { module:`Critical Thinking`, ref:`Confirmation bias`, q:`Cognitive bias: Belief Perseverance / Confirmation Bias.`, a:`Favoring information that confirms existing beliefs and perspectives.` },
  { module:`Critical Thinking`, ref:`Deflection`, q:`Cognitive bias: Deflection.`, a:`Answering the wrong question to steer a conversation away from its original intent.` },
  { module:`Critical Thinking`, ref:`Activated Ignorance`, q:`Cognitive bias: Activated Ignorance.`, a:`Actively using information that is false but mistakenly believed to be true.` },

  /* ── 09 Establishing Expectations ── */
  { module:`Establishing Expectations`, ref:`Importance`, q:`Why is establishing expectations important?`, a:`It identifies goals and clarifies objectives; provides a roadmap; links individual duties to unit standards and the mission; reduces confusion and stress; fosters connection to the broader organizational mission; and drives success as the critical starting point for effective leadership.` },
  { module:`Establishing Expectations`, ref:`Guidelines`, q:`Summarize the six guidelines for establishing expectations.`, a:`Understand the importance; know when and where; communicate clearly; help subordinates connect; seek buy-in; and track progress.` },
  { module:`Establishing Expectations`, ref:`Understand importance`, q:`Guideline: Understand Importance.`, a:`Know why the expectations are being set.` },
  { module:`Establishing Expectations`, ref:`When and where`, q:`Guideline: Know When and Where.`, a:`Recognize that it is a continuous cycle — establish expectations, observe performance, and adjust expectations as needed.` },
  { module:`Establishing Expectations`, ref:`Communicate clearly`, q:`Guideline: Communicate Clearly.`, a:`Ensure expectations are simple and easily understood — and know what your own boss expects first.` },
  { module:`Establishing Expectations`, ref:`Help connect`, q:`Guideline: Help Subordinates Connect.`, a:`Link your expectations to those of senior leadership and to the overall mission.` },
  { module:`Establishing Expectations`, ref:`Seek buy-in`, q:`Guideline: Seek Buy-In.`, a:`Include the team in the process, set achievable goals, maintain a positive tone, and show trust to foster ownership.` },
  { module:`Establishing Expectations`, ref:`Track progress`, q:`Guideline: Track Progress.`, a:`Plan how to monitor activities by outlining steps, setting milestones, tracking progress, and capturing results.` },

  /* ── 10 Conflict Management ── */
  { module:`Conflict Management`, ref:`Organizational sources`, q:`Name the four organizational sources of conflict.`, a:`Communication Factors (misinterpreted, inaccurate, or incomplete information), Structural Factors (issues from organization size, such as information distortion), Rewards (reward systems perceived as unfair or biased), and Resource Interdependence (time, people, or money perceived as scarce).` },
  { module:`Conflict Management`, ref:`Personal factors`, q:`Name the three personal behavior sources of conflict.`, a:`Values (personal values such as religion or politics being questioned or criticized), Perception (different views on fairness or quality, especially when assuming everyone defines terms the same way), and Personality (clashes between uncomplimentary personalities).` },
  { module:`Conflict Management`, ref:`Additional factors`, q:`What three additional factors shape how you handle conflict?`, a:`Who you are dealing with (a commander versus a subordinate), what the stakes are (importance drives assertiveness and cooperation), and what the situation is (time-sensitive settings may limit available styles).` },
  { module:`Conflict Management`, ref:`Two variables`, q:`What two variables underlie both the Thomas-Kilmann and AFNC models?`, a:`Assertiveness or task orientation, and cooperativeness or people orientation.` },
  { module:`Conflict Management`, ref:`Five styles`, q:`Name the five conflict management styles and their AFNC equivalents.`, a:`Competing/Forcing = Insist. Avoiding = Evade. Accommodating = Comply. Compromising = Settle. Collaborating = Cooperate.` },
  { module:`Conflict Management`, ref:`Competing / Insist`, q:`Competing/Forcing (AFNC: Insist).`, a:`High assertiveness and task focus, low cooperation and people focus. Aims to overwhelm an opponent with authority or power. Useful when the objective is paramount, regardless of the relationship.` },
  { module:`Conflict Management`, ref:`Avoiding / Evade`, q:`Avoiding (AFNC: Evade).`, a:`Low assertiveness and low cooperation. A passive approach where the issue is ignored or delayed. Appropriate when the issue is unimportant or more information is needed.` },
  { module:`Conflict Management`, ref:`Accommodating / Comply`, q:`Accommodating (AFNC: Comply).`, a:`Low assertiveness, high cooperation. Giving in to the other person's wishes to preserve the relationship. Useful when the relationship is more important than the task.` },
  { module:`Conflict Management`, ref:`Compromising / Settle`, q:`Compromising (AFNC: Settle).`, a:`Moderate assertiveness and moderate cooperation. Seeks a solution that partially satisfies both parties through mutual concessions. A quick solution when both parties are willing to give something up.` },
  { module:`Conflict Management`, ref:`Collaborating / Cooperate`, q:`Collaborating (AFNC: Cooperate).`, a:`High assertiveness and high cooperation. Aims for a win-win solution that fully satisfies both sides. Requires trust, openness, and shared information.` },

  /* ── 11 Change Management ── */
  { module:`Change Management`, ref:`Lewin model`, q:`Recognize Lewin's Change Management Model.`, a:`Developed in the 1940s by Kurt Lewin. Three stages: Unfreezing, Changing, Refreezing. Each stage has its own opportunities and difficulties.` },
  { module:`Change Management`, ref:`Competing forces`, q:`What two competing forces act on every change effort?`, a:`Driving Forces, which push in a particular direction to produce change, and Restraining Forces, which restrain or decrease the driving forces and inhibit change.` },
  { module:`Change Management`, ref:`Kotter`, q:`How does Kotter's model relate to Lewin's?`, a:`Dr. John Kotter's 8-Step Change model is used to further develop the Unfreezing, Changing, and Refreezing process — steps 1-4 in Unfreezing, 5-6 in Changing, and 7-8 in Refreezing.` },
  { module:`Change Management`, ref:`Kotter 8 steps`, q:`Name Kotter's eight steps in order.`, a:`1) Create Urgency 2) Form a Powerful Coalition 3) Create a Vision 4) Communicate the Vision 5) Remove Obstacles 6) Create Short-Term Wins 7) Build on the Change 8) Anchor the Changes in Organizational Culture.` },
  { module:`Change Management`, ref:`Unfreezing`, q:`Lewin Stage 1: Unfreezing.`, a:`Deliberate management activity to prepare people, processes, and machines for change. Leaders must create awareness and understanding — communication is key, and members must know the "why" and "how." The end goal is to inspire a personal desire to change through buy-in and collaboration.` },
  { module:`Change Management`, ref:`Unfreezing actions`, q:`Leader actions in the Unfreezing stage (Kotter 1-4).`, a:`Create Urgency, Form a Powerful Coalition, Create a Vision, and Communicate the Vision.` },
  { module:`Change Management`, ref:`Changing`, q:`Lewin Stage 2: Changing.`, a:`Leaders enact the proposed vision and change plan. Change may involve technology, tasks, structures, personnel, mission, and more. All change MUST be monitored, and leaders should address concerns or resistance immediately.` },
  { module:`Change Management`, ref:`Changing actions`, q:`Leader actions in the Changing stage (Kotter 5-6).`, a:`5) Remove Obstacles — use the coalition to assist with policy changes, instill knowledge, and develop ability (empowerment). 6) Create Short-Term Wins — quick wins to reach milestones and reduce criticism, and recognize strong performers.` },
  { module:`Change Management`, ref:`Refreezing`, q:`Lewin Stage 3: Refreezing.`, a:`Change efforts can still be derailed before refreezing occurs. Stay engaged and continually evaluate results — is the change achieving desired results, and does it require additional support or resources? Formalize processes and ensure long-term stability.` },
  { module:`Change Management`, ref:`Refreezing actions`, q:`Leader actions in the Refreezing stage (Kotter 7-8).`, a:`7) Build on the Change — analyze what went right and wrong and remain engaged. 8) Anchor the Changes in Organizational Culture — update instructions and policy, incorporate the change into training, and set new goals.` },
  { module:`Change Management`, ref:`Resistance stage`, q:`In which stage is resistance most commonly encountered?`, a:`The Unfreezing stage.` },
  { module:`Change Management`, ref:`Resistance types`, q:`Identify the common forms of resistance to change.`, a:`Distrust (members do not trust leadership's motives or the change), Uncertainty (fear of the unknown), Self-Interest (the perception that the change costs the member something personally), Different Perception or No Felt Need to Change (members see no problem with the current state), and Over-Determination (structures, policies, and processes built to reinforce stability inherently resist change).` },
  { module:`Change Management`, ref:`Over-Determination`, q:`Define over-determination as a source of resistance.`, a:`Organizational structures, policies, and processes are built to reinforce stability, which inherently resists change.` },
  { module:`Change Management`, ref:`Reducing resistance`, q:`List the methods leaders use to reduce and manage resistance to change.`, a:`Follow the plan; communicate; create urgency and a shared vision; form a powerful coalition; provide support; remove barriers to change; set short-term and long-term goals; address concerns and resistance immediately; analyze and evaluate changes; and anchor the change.` },
  { module:`Change Management`, ref:`Communication`, q:`What is the primary tool against distrust and uncertainty?`, a:`Communication — creating awareness and understanding so members know the "why" and the "how" of the change.` },

  /* ── 12 Inspiring Action ── */
  { module:`Inspiring Action`, ref:`Mission statement`, q:`Mission statement — key traits.`, a:`Focuses on the present; defines the organization's purpose and what it does; answers the "what" and "who"; guides daily operations and decision-making.` },
  { module:`Inspiring Action`, ref:`Vision statement`, q:`Vision statement — key traits.`, a:`Focuses on the future; describes the organization's long-term aspirations; answers the "why" and "how"; provides inspiration, hope, and a sense of direction.` },
  { module:`Inspiring Action`, ref:`Mission vs vision`, q:`Contrast mission and vision statements.`, a:`Mission is present-focused and defines purpose (what and who). Vision is future-focused and describes aspirations (why and how).` },
  { module:`Inspiring Action`, ref:`SWOT`, q:`What does SWOT stand for and what is its purpose?`, a:`Strengths, Weaknesses, Opportunities, Threats. It is a strategic planning tool used to identify priorities and make decisions.` },
  { module:`Inspiring Action`, ref:`SWOT internal/external`, q:`SWOT — internal versus external factors.`, a:`Internal: Strengths and Weaknesses. External: Opportunities and Threats.` },
  { module:`Inspiring Action`, ref:`SWOT function`, q:`What does a SWOT analysis do for a leader?`, a:`Reveals positive forces to leverage and potential problems to address; helps prioritize initiatives and allocate resources effectively; and provides a foundation for creating a tangible action plan.` },
  { module:`Inspiring Action`, ref:`Articulate vision`, q:`Technique: Articulate the Vision.`, a:`Communicate a clear, well-understood, and inspiring vision. Use storytelling to make it relatable and memorable.` },
  { module:`Inspiring Action`, ref:`Frame meaning`, q:`Technique: Get Their Attention and Frame Meaning.`, a:`Explain the "why" behind the vision to give it purpose, and create a dialogue rather than a monologue by inviting questions and feedback.` },
  { module:`Inspiring Action`, ref:`Enable action`, q:`Technique: Enable Action.`, a:`Integrate the vision into the organization's daily activities, and encourage two-way communication while welcoming feedback for refinement.` },
  { module:`Inspiring Action`, ref:`Reinforce action`, q:`Technique: Reinforce Action and Celebrate Success.`, a:`Regularly discuss the vision in meetings and communications to keep it a priority, and acknowledge progress and celebrate milestones to maintain motivation.` },

  /* ── 13 Organizational Climate ── */
  { module:`Organizational Climate`, ref:`Culture`, q:`Organizational culture — define and give an example.`, a:`Long-term, ingrained ideologies, values, and norms — foundational beliefs and established traditions. Example: ALWAYS WITH HONOR.` },
  { module:`Organizational Climate`, ref:`Climate`, q:`Organizational climate — define and give an example.`, a:`Short-term, adjustable attitudes and perceptions — current moods and feelings, and a product of the culture. Example: how personnel currently and collectively feel about wearing reflective belts in the dorms in PTU.` },
  { module:`Organizational Climate`, ref:`Contrast`, q:`Contrast climate and culture.`, a:`Culture is long-term and ingrained — values, norms, and traditions. Climate is short-term and adjustable — current attitudes and perceptions, and a product of the culture.` },
  { module:`Organizational Climate`, ref:`Physical safety`, q:`Strategy: physical safety.`, a:`Safeguard troops from harm, eliminate hazards, and control risks through proper training and safety protocols.` },
  { module:`Organizational Climate`, ref:`Emotional safety`, q:`Strategy: emotional safety.`, a:`Foster respect, openness, and trust; encourage calculated risks without fear of failure or harsh repercussions. Uphold a zero tolerance policy for harassment and sexual assault.` },
  { module:`Organizational Climate`, ref:`High standards`, q:`Strategy: high standards.`, a:`Challenge personnel to reach new heights and conquer new challenges; clearly define standards by establishing and communicating expectations; and connect individual expectations to the success of the overall mission.` },
  { module:`Organizational Climate`, ref:`Address your unit`, q:`Changing climate: Address Your Unit.`, a:`Be transparent with survey results such as the DEOCS (Defense Equal Opportunity Climate Survey); discuss negative and positive trends and potential mission impact; and offer follow-up services like one-on-one meetings or chaplain services.` },
  { module:`Organizational Climate`, ref:`Inspire action`, q:`Changing climate: Inspire Action.`, a:`Communicate the mission, vision, and priorities often and in various ways; empower subordinates, build trust, and foster collaboration; and reinforce positive actions by showing appreciation and celebrating contributions.` },
  { module:`Organizational Climate`, ref:`Little things`, q:`Changing climate: Focus on the Little Things.`, a:`A leader's influence is constant and comes from every action — highlighting achievements, consistently providing feedback, enforcing policy, or offering simple words of encouragement.` },

  /* ── 14 National Security ── */
  { module:`National Security`, ref:`IOP definition`, q:`Define instruments of national power.`, a:`The tools a nation uses to influence other nations, international organizations, or non-state actors. The core four are DIME.` },
  { module:`National Security`, ref:`DIME`, q:`What does DIME stand for?`, a:`Diplomatic, Informational, Military, Economic.` },
  { module:`National Security`, ref:`Diplomatic`, q:`Diplomatic instrument of power.`, a:`The PRINCIPAL instrument for engaging other states and foreign groups to advance national values, interests, and objectives, and to solicit foreign support for military operations. The principal means of organizing coalitions and alliances. Examples: embassies and ambassadors, recognition, negotiations, treaties, international forums.` },
  { module:`National Security`, ref:`Informational`, q:`Informational instrument of power.`, a:`Determined by factors such as population education and skill levels — the more literate a nation, the more effectively it can wield informational power. Includes cultural and student exchanges, international conferences, and covert deception and misinformation programs. Examples: public diplomacy, communications resources, spokespersons, and the timing, media, and venue of announcements.` },
  { module:`National Security`, ref:`Military`, q:`Military instrument of power.`, a:`FUNDAMENTALLY COERCIVE in nature. Generates effects through the application or threat of force to compel an adversary to take or discontinue an action. Also useful in non-conflict situations such as foreign relief. Varies in purpose, scale, risk, and combat intensity across the Range of Military Operations (ROMO).` },
  { module:`National Security`, ref:`Economic`, q:`Economic instrument of power.`, a:`A strong economy with free access to global markets is a fundamental engine of general welfare and an enabler of a strong national defense. Derived from population, natural resources, and monetary stability. Examples: trade policies, fiscal and monetary policies, embargoes, tariffs, assistance, and sanctions.` },
  { module:`National Security`, ref:`Interaction`, q:`How do the instruments of power interact?`, a:`They are interrelated and work best when orchestrated together — they should rarely, if ever, be used in isolation. Departments and agencies interact to build mutual understanding of capabilities, limitations, and consequences, and to identify how military and nonmilitary capabilities complement each other.` },
  { module:`National Security`, ref:`Ultimate authority`, q:`Who has ultimate responsibility for national security policy and the IOPs?`, a:`The President — responsible for developing, coordinating, and employing the instruments of national power.` },
  { module:`National Security`, ref:`NSS`, q:`What is the National Security Strategy (NSS)?`, a:`The document describing how the President plans to use the instruments of national power to achieve national objectives. Subordinate departments and agencies translate and refine it into their own strategies, such as the NDS and then the NMS.` },
  { module:`National Security`, ref:`DIME-FIL`, q:`What is DIME-FIL?`, a:`The joint community's expansion of DIME, adding Financial, Intelligence, and Law Enforcement under a whole of government approach.` },
  { module:`National Security`, ref:`Lykke's model`, q:`What is Lykke's model?`, a:`Ends, Ways, and Means — developed by Col Arthur F. Lykke Jr., it became the dominant US Army strategy model in the 1980s.` },
  { module:`National Security`, ref:`Ends`, q:`Lykke: Ends.`, a:`WHAT is to be accomplished — the objectives that create or contribute to the desired end state and ultimately serve national interests. Expressed with verbs. Examples: deter war, promote regional stability, denuclearize the peninsula.` },
  { module:`National Security`, ref:`Ways`, q:`Lykke: Ways.`, a:`HOW the ends are accomplished — the strategic concepts and courses of action. Must be explicit enough to give planning guidance to those who implement and resource it. Examples: containment, forward defense, mutually assured destruction, forward presence.` },
  { module:`National Security`, ref:`Means`, q:`Lykke: Means.`, a:`WITH WHAT — the specific resources. Tangible: forces, people, equipment, money, facilities. Intangible: will, courage, intellect.` },
  { module:`National Security`, ref:`Test for a way`, q:`How do you test whether something is a "way"?`, a:`Ask "in order to do what?" — the answer reveals the real objective, which is the End.` },
  { module:`National Security`, ref:`Worked example`, q:`Give a worked ends-ways-means example.`, a:`End = defend the United States (what). Way = develop, build, or establish a larger force (how). Means = national manpower reserves, money, and training facilities (with what).` },
  { module:`National Security`, ref:`Linkage`, q:`How do national objectives link to the instruments of power?`, a:`National objectives are the ENDS and the four instruments of power are the MEANS. These are continuously evaluated and matched.` },
  { module:`National Security`, ref:`Risk`, q:`Where does risk come from in strategy?`, a:`Risk is the gap that appears when ends, ways, and means are out of balance.` },

  /* ── 15 What is War ── */
  { module:`What is War`, ref:`Clausewitz`, q:`Who was Carl von Clausewitz?`, a:`A Prussian staff officer (1780-1831) who fought Napoleon and later served as President of the Prussian War Academy. Author of the eight-volume Vom Kriege (On War).` },
  { module:`What is War`, ref:`Definition of war`, q:`Clausewitz's definition of war.`, a:`War is an act of violence to compel our opponent to do our will. In its simplest form, it is a duel on an extensive scale.` },
  { module:`What is War`, ref:`Two aspects`, q:`What two inseparable aspects does the definition of war reveal?`, a:`Policy — the "will" a nation-state seeks to impose, which answers WHY the war is fought. Violence — the raw physical essence, the "act" itself, the application of force and destruction of the enemy's armed forces.` },
  { module:`What is War`, ref:`Two themes`, q:`Identify the two basic themes of war.`, a:`The Nature of war (unchanging and permanent) and the Character of war (in constant flux).` },
  { module:`What is War`, ref:`Nature of war`, q:`Describe the nature of war.`, a:`Unchanging and permanent — war's essential, unalterable purpose is to use violence, or the threat of it, to achieve a political objective. War is a profoundly human activity tied to unchanging human nature: passion, chance, and political aim. Violence, human fallibility, and politics are as relevant today as in the age of empires.` },
  { module:`What is War`, ref:`Character of war`, q:`Describe the character of war.`, a:`In constant flux — HOW warfare is conducted, its appearance and form. It reflects the political, economic, military, and technological dynamics of a given society. Examples: tanks and airplanes in WWI, atomic weapons in WWII, widespread drone use in the Russia-Ukraine war.` },
  { module:`What is War`, ref:`Three truths`, q:`Identify the three enduring truths of war.`, a:`1) War is an instrument of policy. 2) War is a complex and chaotic human endeavor. 3) War is a clash of opposing wills.` },
  { module:`What is War`, ref:`Truth 1`, q:`Enduring truth: war is an instrument of policy.`, a:`War is an act of violence but it is not an end. War between nations always starts from a political condition and motive, so war is a political act. Once begun, war does not set aside policy — the original political motive must be the first and highest consideration. The political view is the object; war is the means.` },
  { module:`What is War`, ref:`Truth 1 example`, q:`What example illustrates war as an instrument of policy?`, a:`The First Gulf War (1991) — the political object was clear and limited (liberate Kuwait). Once achieved by military force, the war was halted: a near-perfect subordination of military means to the political goal.` },
  { module:`What is War`, ref:`Truth 2`, q:`Enduring truth: war is a complex and chaotic human endeavor.`, a:`War appears simple without personal experience, but the simplest actions become difficult. These difficulties accumulate and produce friction — what distinguishes real war from war on paper. The military machine is composed entirely of individuals with their own frailties: danger plus human exertion equals friction.` },
  { module:`What is War`, ref:`Truth 3`, q:`Enduring truth: war is a clash of opposing wills.`, a:`War is not waged against an inanimate mass but against a living, calculating, and adaptive opponent. It is always the shock of two hostile bodies in collision — as long as the enemy is not defeated, I must recognize that he may defeat me. This dynamic is the engine that drives conflict forward.` },
  { module:`What is War`, ref:`Levels of war`, q:`Name the three levels of war and what determines the level.`, a:`Strategic, Operational, and Tactical. It is NOT the weapon used, but the desired EFFECT, that determines the level.` },
  { module:`What is War`, ref:`Strategic level`, q:`Strategic level of war.`, a:`Answers WHY and WITH WHAT. National security objectives are set and all instruments of power (DIME) are made available. Effects impair the adversary's overall ability to carry on the war and neutralize fundamental centers of gravity. Example: an air strike to remove an enemy regime and destroy national will.` },
  { module:`What is War`, ref:`Operational level`, q:`Operational level of war.`, a:`Answers WHAT to affect, with WHAT courses of action, in WHAT order, and for WHAT duration. The realm of campaigns and major operations that sequence tactical actions to produce effects exceeding the sum of their parts. Example: B-52 strikes on an enemy integrated air defense system (IADS).` },
  { module:`What is War`, ref:`Tactical level`, q:`Tactical level of war.`, a:`Answers HOW. Individual battles and engagements — direct and tangible violence, the duel in its most literal sense. Focused on defeating an enemy force at a specific time and place. Example: an A-10 conducting close air support for friendly forces in contact.` },
  { module:`What is War`, ref:`Three factors`, q:`List the three factors that dominate war.`, a:`Fog, Friction, and Chance.` },
  { module:`What is War`, ref:`Fog`, q:`Define fog, with an example.`, a:`The imperfect knowledge within warfare — how difficult it is to see and understand what is going on once the battle starts. Example: the Battle of the Bulge (1944), where Allied high command, in a fog of overconfidence and faulty intelligence, was completely surprised by the German offensive through the Ardennes.` },
  { module:`What is War`, ref:`Friction`, q:`Define friction, with an example.`, a:`The accumulation of thousands of little things that force plans to go awry. Example: Operation BARBAROSSA (1941), where mud, logistical breakdowns over vast distances, and minor delays compounding into major ones halted the advance before Moscow.` },
  { module:`What is War`, ref:`Chance`, q:`Define chance, with an example.`, a:`Dumb luck and fortune, which play an enormous role in war. Example: Operation VALKYRIE (1944), where the briefcase bomb's blast was deflected by a heavy oak table leg, sparing Hitler. Also the USS Indianapolis, which the Japanese commander testified was a lucky shot on one last look through the periscope.` },
  { module:`What is War`, ref:`Traditional warfare`, q:`Define traditional warfare.`, a:`A violent struggle for domination between nation-states. Uses force-on-force operations with conventional capabilities. Objective: disarm the enemy — destroy his military, conquer his country, subdue his will.` },
  { module:`What is War`, ref:`Irregular warfare`, q:`Define irregular warfare.`, a:`A violent struggle among state and non-state actors for legitimacy and influence over relevant populations. Uses indirect and asymmetric approaches. Objective: raise the price of success until the enemy's political object is no longer equal in value, and weary out the enemy through gradual exhaustion of physical powers and will.` },
  { module:`What is War`, ref:`Forms compared`, q:`Are traditional and irregular warfare mutually exclusive?`, a:`No — they are not mutually exclusive, but they differ significantly in strategy and conduct.` },
  { module:`What is War`, ref:`Traditional example`, q:`Example of traditional warfare.`, a:`The Napoleonic Wars — at Austerlitz (1805) Napoleon achieved decisive destruction of the Austro-Russian forces in a single day, leading Austria to sue for peace. The "bloody solution of the crisis."` },
  { module:`What is War`, ref:`Irregular example`, q:`Example of irregular warfare.`, a:`The Soviet-Afghan War (1979-1989) — the Mujahideen could not defeat the Soviets conventionally, so they waged a protracted guerrilla campaign draining Soviet resources and manpower until the price of occupation became too high.` },
  { module:`What is War`, ref:`Wonderful Trinity`, q:`What is Clausewitz's "wonderful trinity"?`, a:`Three competing tendencies, each a different lawgiver: 1) Primordial violence, hatred, and blind instinct — the passion of the PEOPLE. 2) The play of chance and probability — the courage and talent of the COMMANDER and MILITARY. 3) Subordination as a political instrument — the pure reason of the GOVERNMENT. The great problem is keeping these tendencies in balance.` },

  /* ── 16 What the DAF Brings ── */
  { module:`What the DAF Brings`, ref:`Airpower`, q:`Define airpower and its purpose.`, a:`The ability to project military power through control and exploitation in, from, and through the air (AFDP 3-0). Historically an asymmetric advantage and a fundamental component of the military instrument of power. It creates effects across a theater or the globe, bypasses fielded forces to strike enemy centers of gravity directly, wrests the initiative, sets the terms of battle, and dictates the tempo of operations.` },
  { module:`What the DAF Brings`, ref:`USAF contributions`, q:`What three things does the Air Force provide the Nation?`, a:`Global Vigilance, Global Reach, and Global Power.` },
  { module:`What the DAF Brings`, ref:`Global Vigilance`, q:`Global Vigilance.`, a:`Gain and maintain awareness anywhere; provide warning; determine intent, opportunity, capability, or vulnerability.` },
  { module:`What the DAF Brings`, ref:`Global Reach`, q:`Global Reach.`, a:`Project military capability responsively with unsurpassed velocity and precision; rapidly supply, position, or reposition joint forces.` },
  { module:`What the DAF Brings`, ref:`Global Power`, q:`Global Power.`, a:`Hold at risk or strike any target anywhere; assert sovereignty; create swift, decisive, precise effects.` },
  { module:`What the DAF Brings`, ref:`Spacepower`, q:`Define spacepower and its purpose.`, a:`The ability to accomplish military objectives in, from, and to the space domain (SFDD-1). It requires safeguarding US commercial, civil, intelligence, and military ability to access, maneuver within, and exploit space without prohibitive interference, and supports deterrence by demonstrating the ability and willingness to impose costs and deny an adversary's benefit from hostile action.` },
  { module:`What the DAF Brings`, ref:`USSF responsibilities`, q:`Name the three cornerstone responsibilities of the Space Force.`, a:`Preserve Freedom of Action, Enable Joint Lethality and Effectiveness, and Provide Independent Options.` },
  { module:`What the DAF Brings`, ref:`Competitive Endurance`, q:`What is Competitive Endurance and its three tenets?`, a:`The USSF approach to achieving space superiority in crisis or conflict while maintaining the long-term sustainability of space. Tenets: 1) Avoid Operational Surprise 2) Deny First-Mover Advantage 3) Conduct Responsible Counterspace Operations.` },
  { module:`What the DAF Brings`, ref:`USAF functions`, q:`Name the five USAF core functions.`, a:`Air Superiority; Global Precision Attack; Rapid Global Mobility; Global ISR; and Command and Control (C2).` },
  { module:`What the DAF Brings`, ref:`Renamed functions`, q:`Which two USAF core functions were recently renamed?`, a:`Global Strike became GLOBAL PRECISION ATTACK, and ISR became GLOBAL ISR (AFDP 3-0, 22 Jan 2025).` },
  { module:`What the DAF Brings`, ref:`Air Superiority`, q:`Purpose: Air Superiority.`, a:`Control of the air — a prerequisite to success in modern operations. Provides freedom of action and freedom of movement and prevents enemy air and missile threats from interfering. Degrees: air parity, local air superiority, and air supremacy. Enabling operation: counterair (OCA and DCA).` },
  { module:`What the DAF Brings`, ref:`Global Precision Attack`, q:`Purpose: Global Precision Attack.`, a:`Crisis response and escalation control; holds any target at risk. Includes CAS, interdiction, SOF insertion, and strikes on adversary vital centers, delivered by bombers, missiles, fighters, and SOF platforms.` },
  { module:`What the DAF Brings`, ref:`Rapid Global Mobility`, q:`Purpose: Rapid Global Mobility.`, a:`Delivery on demand — projects American power quickly anywhere on Earth. Enabling operations: airlift, air refueling (AR), and aeromedical evacuation (AE).` },
  { module:`What the DAF Brings`, ref:`Global ISR`, q:`Purpose: Global ISR.`, a:`Minimizes uncertainty about adversaries and their capabilities, strengthens deterrence, and gives commanders a decision-making advantage. The foundation for joint, interagency, and coalition success. Enabling operations: airborne ISR and targeting.` },
  { module:`What the DAF Brings`, ref:`Command and Control`, q:`Purpose: Command and Control (C2).`, a:`Right information to the right person at the right time — sense, make sense, and act. Allows joint teams to operate globally at high tempo. Examples: AOCs, AWACS, JSTARS.` },
  { module:`What the DAF Brings`, ref:`Joint functions`, q:`What are the seven joint functions the core functions feed?`, a:`Command and control, information, intelligence, fires, movement and maneuver, protection, and sustainment.` },
  { module:`What the DAF Brings`, ref:`USSF functions`, q:`Name the four USSF core and enterprise functions.`, a:`Space Control, Global Mission Operations, and Space Access (core), plus Enterprise (enterprise function).` },
  { module:`What the DAF Brings`, ref:`Space Control`, q:`Purpose: Space Control.`, a:`Contest and control the space domain — the desired outcome is space superiority. Consists of offensive and defensive counterspace operations. Mission areas: orbital warfare, electromagnetic warfare, and cyberspace warfare.` },
  { module:`What the DAF Brings`, ref:`Global Mission Operations`, q:`Purpose: Global Mission Operations.`, a:`Deliver space effects in support of military operations — the space-enabled combat edge that lets the US out-see, out-shoot, out-maneuver, and out-communicate any adversary. Mission areas: SATCOM, navigation warfare, missile warning and tracking, space-based sensing and targeting, and theater EW.` },
  { module:`What the DAF Brings`, ref:`Space Access`, q:`Purpose: Space Access.`, a:`Movement and support of military equipment and personnel into, through, and back from the space domain — it sets the space theater. Mission areas: satellite control, spacelift, and launch range control.` },
  { module:`What the DAF Brings`, ref:`Enterprise`, q:`Purpose: the Enterprise function.`, a:`Four cross-cutting enablers of all core functions: intelligence, cyberspace operations, command and control, and space domain awareness (SDA).` },
  { module:`What the DAF Brings`, ref:`SDA note`, q:`Where did Space Domain Awareness go under the new construct?`, a:`SDA did not disappear — the old five USSF competencies collapsed into three core functions, and SDA moved under the ENTERPRISE function.` },
  { module:`What the DAF Brings`, ref:`Doctrine role`, q:`What is the role of doctrine?`, a:`Fundamental principles guiding military actions. It is official advice but NOT directive, so it requires judgment in application. It evolves as theory, experience, and technologies change, and provides an 80-90 percent solution when properly applied.` },
  { module:`What the DAF Brings`, ref:`Doctrine purpose`, q:`What is the purpose of doctrine?`, a:`It describes and guides the proper use of airpower and spacepower, and helps Airmen and Guardians understand their mission, organization, authority, and support structures within the joint force.` },

  /* ── 17 Military Planning ── */
  { module:`Military Planning`, ref:`Why plan`, q:`Why does the military use a formal planning process?`, a:`A structured framework cannot guarantee success, but it minimizes risk and maximizes the chances of success and forces a realistic assessment of challenges and risks.` },
  { module:`Military Planning`, ref:`What planning does`, q:`What does a formal planning process do for you?`, a:`Forces you to explore alternatives, challenge assumptions, consider different perspectives, and justify your reasoning; cultivates adaptability and creative problem-solving; fosters disciplined initiative and supports decentralized execution by distributing commander's intent; and gives the commander the ability to make timely decisions in dynamic and complex environments.` },
  { module:`Military Planning`, ref:`Eagle Claw`, q:`What was Operation EAGLE CLAW?`, a:`The failed 24 April 1980 rescue of 52 American hostages in Tehran. Helicopter losses left five operational aircraft against a six-helicopter minimum, and Col Charles Beckwith aborted. During withdrawal from Desert One a helicopter collided with a parked C-130, killing eight American servicemen (five Airmen and three Marines). The hostages remained captive another 264 days.` },
  { module:`Military Planning`, ref:`Eagle Claw failures`, q:`Name the six contributing planning failures of EAGLE CLAW.`, a:`1) Overly complex plan 2) Insufficient rehearsals 3) Inadequate weather contingency planning 4) Lack of redundancy 5) Interservice coordination breakdowns 6) Over-reliance on advanced technology.` },
  { module:`Military Planning`, ref:`Desert Storm`, q:`How does DESERT STORM contrast with EAGLE CLAW?`, a:`Structured planning produced a clear primary objective (swiftly and decisively liberate Kuwait) with clear metrics for success, and emphasis on intelligence and targeting identified key Iraqi weaknesses. The process also defined the limits of intervention — no regime change — which prevented mission creep and maintained international support.` },
  { module:`Military Planning`, ref:`Seven steps`, q:`Name the seven steps of the Air Force Planning Process.`, a:`1) Planning Initiation 2) Mission Analysis 3) COA Development 4) COA Analysis and Wargaming 5) COA Comparison 6) COA Approval 7) Plan or Order Development.` },
  { module:`Military Planning`, ref:`Three bands`, q:`How are the seven planning steps grouped?`, a:`Strategic Guidance, then Developing the Concept, then Developing the Plan.` },
  { module:`Military Planning`, ref:`Step 1`, q:`Step 1: Planning Initiation.`, a:`Kicks off the process. Craft a clear, concise problem statement using factual data (the 5 Ws plus How). Focus on defining the problem, not proposing solutions. Must align with commander's intent and be realistic in scope. Deliverables: a well-defined problem statement and a planning team.` },
  { module:`Military Planning`, ref:`Step 2`, q:`Step 2: Mission Analysis.`, a:`Arguably the most critical step. Refine the mission statement with a clear vision of the end state, analyzed in the context of the operational environment. Define constraints (what you cannot do) and restraints (your limitations), and understand adversary capabilities, intentions, and vulnerabilities.` },
  { module:`Military Planning`, ref:`Constraints vs restraints`, q:`Constraints versus restraints.`, a:`Constraints are what you cannot do. Restraints are your limitations.` },
  { module:`Military Planning`, ref:`Step 3`, q:`Step 3: COA Development.`, a:`Generate multiple potential approaches — akin to brainstorming. Each COA is a potential path to the end state while minimizing risk. Provide a sequencing of major actions and desired effects, and craft a COA statement answering the 5 Ws and how. Deliverable: a COA briefing.` },
  { module:`Military Planning`, ref:`Step 4`, q:`Step 4: COA Analysis and Wargaming.`, a:`Rigorously evaluate each COA for strengths, weaknesses, risks, and consequences, considering time, resources, terrain, weather, and enemy capabilities. Uncovers what-if scenarios and unintended consequences. Deliverable: the most promising option with clear justification.` },
  { module:`Military Planning`, ref:`Step 5`, q:`Step 5: COA Comparison.`, a:`Systematically rate each COA on the advantages, disadvantages, and risks found in wargaming, using rating criteria. Deliverable: a recommended COA.` },
  { module:`Military Planning`, ref:`Step 6`, q:`Step 6: COA Approval.`, a:`Deliver a decision brief highlighting differences between COAs with an overall recommendation. THE COMMANDER DECIDES. Deliverable: a commander-approved COA.` },
  { module:`Military Planning`, ref:`Commander's options`, q:`What six options does the commander have at COA Approval?`, a:`1) Concur with the recommended COA 2) Select a different COA 3) Modify a COA 4) Combine aspects of multiple COAs 5) Direct development of different COAs 6) Request additional information.` },
  { module:`Military Planning`, ref:`Step 7`, q:`Step 7: Plan or Order Development.`, a:`Develop the detailed OPLAN (long-range planning) or OPORD (immediate execution) from the approved COA. Deliverables: a finalized OPLAN or OPORD and a mission rehearsal plan.` },
  { module:`Military Planning`, ref:`OPLAN vs OPORD`, q:`OPLAN versus OPORD.`, a:`An OPLAN is for long-range planning; an OPORD is for immediate execution.` },
  { module:`Military Planning`, ref:`Iterative`, q:`Is the planning process linear?`, a:`The framework is linear but the process is iterative — each step builds on the previous one, and arrows lead back from Step 7 to Step 2, or even Step 1. Planning is often revisited and refined.` },
  { module:`Military Planning`, ref:`COA attributes`, q:`Name the five attributes of a quality COA.`, a:`Adequate, Feasible, Acceptable, Distinguishable, and Complete. Mnemonic: A-F-A-D-C, "A Fully Adequate Decision Checklist."` },
  { module:`Military Planning`, ref:`Adequate`, q:`COA attribute: Adequate.`, a:`Will this COA achieve the objective? Does it align with the overall mission and strategic goals, and is it the best way to achieve the objective?` },
  { module:`Military Planning`, ref:`Feasible`, q:`COA attribute: Feasible.`, a:`Is it executable within available time and space? Do we have enough resources, the necessary skills and expertise, and are there legal or regulatory constraints?` },
  { module:`Military Planning`, ref:`Acceptable`, q:`COA attribute: Acceptable.`, a:`Is the potential benefit worth the risk? What are the potential negative consequences and ethical considerations?` },
  { module:`Military Planning`, ref:`Distinguishable`, q:`COA attribute: Distinguishable.`, a:`How is this COA different from the others? Does it offer a unique approach, and what are its advantages and disadvantages relative to the others?` },
  { module:`Military Planning`, ref:`Complete`, q:`COA attribute: Complete.`, a:`Does it incorporate all critical tasks and the full scope of the operation? Does it define roles and responsibilities, include a realistic timeline, and identify risks and mitigation strategies?` },
  { module:`Military Planning`, ref:`COA briefing`, q:`What are the elements of a solid COA briefing?`, a:`Purpose, situation overview, mission statement, assumptions, and constraints and limitations; presentation of the COAs with major tasks, timeline, and end state; an overview of resource support and a risk assessment with mitigation strategies; and justification for why a particular COA is best.` },
  { module:`Military Planning`, ref:`Evaluation methods`, q:`Summarize the methods used to evaluate COAs.`, a:`Wargaming; an evaluation matrix scoring COAs against rating criteria; weighted criteria assigning relative importance before scoring; pairwise or head-to-head comparison analyzing COAs two at a time; sensitivity analysis examining how rankings would change if assumptions or conditions changed; and trade-off identification.` },
  { module:`Military Planning`, ref:`Pairwise`, q:`Evaluation method: pairwise comparison.`, a:`Analyze COAs two at a time, identifying which is superior in each category and why, then count the number of times each COA is deemed superior to determine relative ranking.` },
  { module:`Military Planning`, ref:`Sensitivity analysis`, q:`Evaluation method: sensitivity analysis.`, a:`Examine how the ranking would change if certain assumptions or conditions changed.` },
  { module:`Military Planning`, ref:`Recommendation`, q:`Against what should a recommendation always be presented?`, a:`The commander's priorities and risk tolerance.` },
  { module:`Military Planning`, ref:`Wargaming purpose`, q:`Recall the purpose of wargaming.`, a:`Wargames provide a structured environment to simplify complex problems, challenge assumptions, enable the team to learn, visualize the flow of operations, simulate the human decision-making processes inherent in war including fog and friction, and let the team experience the consequences of their actions against a thinking adversary.` },
  { module:`Military Planning`, ref:`Wargame structure`, q:`How is a wargame structured?`, a:`A table-top exercise pitting a Blue Team (friendly forces) executing the COAs against a Red Team (adversary) reacting and countering — a chess game of action, reaction, and counteraction.` },

  /* ── 18 How the DAF Deploys ── */
  { module:`How the DAF Deploys`, ref:`AFFORGEN purpose`, q:`Identify the purpose of AFFORGEN.`, a:`Present sustainable, predictable forces to Joint Force Commanders; enable operational preparedness and readiness recovery; counter long-term strategic competition; and provide a clearer means of projecting and assessing risk and operational tempo.` },
  { module:`How the DAF Deploys`, ref:`SPAFORGEN purpose`, q:`Identify the purpose of SPAFORGEN.`, a:`Prepare Guardians for a congested, contested space domain; establish a predictable, standard battle rhythm; articulate risk, capacity, and readiness to commanders; and transform the force we field into the force we present to combatant commanders.` },
  { module:`How the DAF Deploys`, ref:`AFFORGEN phases`, q:`Cite the four AFFORGEN phases and the cycle length.`, a:`Reset, Prepare, Ready, and Commit — a 24-month cycle with six months in each phase. Ready means available to deploy; Commit is the deployment and employment window.` },
  { module:`How the DAF Deploys`, ref:`SPAFORGEN phases`, q:`Cite the three SPAFORGEN phases.`, a:`Prepare, Ready, and Commit.` },
  { module:`How the DAF Deploys`, ref:`Memory hook`, q:`How does SPAFORGEN differ from AFFORGEN?`, a:`SPAFORGEN is AFFORGEN minus Reset — Guardians largely fight in place, so there is no reconstitution phase.` },
  { module:`How the DAF Deploys`, ref:`Readiness`, q:`Define readiness.`, a:`The ability to fulfill mission requirements.` },
  { module:`How the DAF Deploys`, ref:`Your role`, q:`What is your role in readiness?`, a:`Maintain readiness — training, medical, fitness, personal affairs, and mental preparedness — and know and plan around your deployment eligibility window.` },
  { module:`How the DAF Deploys`, ref:`Leader role`, q:`What is the leader's role in readiness?`, a:`Instill a culture of readiness and provide the resources for Airmen and Guardians to be ready.` },

  /* ── 19 Military Justice ── */
  { module:`Military Justice`, ref:`UCMJ`, q:`Identify the function of the UCMJ.`, a:`Federal law that is the basis of the military justice system. It modified and consolidated the Articles of War, the Articles for the Government of the Navy, and the Disciplinary Laws of the Coast Guard. It contains the Punitive Articles (77-134) and applies to all members of the armed forces worldwide.` },
  { module:`Military Justice`, ref:`Punitive Articles`, q:`Which articles are the Punitive Articles?`, a:`Articles 77 through 134 of the UCMJ.` },
  { module:`Military Justice`, ref:`MCM`, q:`Identify the function of the Manual for Courts-Martial.`, a:`Implemented by Executive Order from the President and has the full force and effect of law. It provides detailed rules and procedures for implementing the UCMJ and contains the full texts of the UCMJ and the US Constitution, the rules of evidence, and guides for writing charges.` },
  { module:`Military Justice`, ref:`Unique crimes`, q:`Name three crimes unique to the military and their articles.`, a:`AWOL (Article 86), Disrespect Toward a Superior (Article 89), and Failure to Obey a Lawful Order (Article 92).` },
  { module:`Military Justice`, ref:`Why a system`, q:`Why is a military justice system needed?`, a:`It addresses crimes unique to the military with no civilian equivalent; it is a driving force behind military discipline, which is critical to good order, efficiency, and effectiveness; and it provides a transportable legal system that applies worldwide, since the US Constitution does not extend US judicial power to foreign soil.` },
  { module:`Military Justice`, ref:`Article 31`, q:`Explain the right against compulsory self-incrimination (Article 31).`, a:`The military counterpart to the Fifth Amendment and Miranda warnings. Members must be informed of the nature of the suspected offense, have the right to remain silent and to stop questioning at any time, and any statements made can be used against them in a court-martial.` },
  { module:`Military Justice`, ref:`Article 31 violations`, q:`What happens to statements obtained without an Article 31 advisement?`, a:`They are inadmissible — as are statements obtained through coercion or unlawful influence.` },
  { module:`Military Justice`, ref:`Right to counsel`, q:`Explain the right to counsel.`, a:`Free military counsel is provided to all accused before summary, special, and general courts-martial, and to members offered Article 15 punishment. Counsel is provided by the Area Defense Counsel (ADC); civilian counsel may be hired at the member's own expense.` },
  { module:`Military Justice`, ref:`Search and seizure`, q:`Explain protection against unreasonable search and seizure.`, a:`Commanders can authorize searches in areas under their authority, and the SJA should be consulted before a search or seizure in most cases. Warrants are required for searches of personal property outside a commander's authority. Health and welfare inspections are permissible but cannot be a pretext for a criminal search.` },
  { module:`Military Justice`, ref:`Illegal search`, q:`What happens to evidence seized in an illegal search or inspection?`, a:`It cannot be used for an Article 15 or a court-martial.` },
  { module:`Military Justice`, ref:`Preventive discipline`, q:`Define preventive discipline.`, a:`The first line of discipline — action taken to encourage members to follow standards and prevent infractions before they occur. The objective is to encourage self-discipline rather than have discipline imposed by superiors. It communicates standards, explains the reasoning behind them, encourages member participation, and states standards positively ("Safety first!") rather than negatively.` },
  { module:`Military Justice`, ref:`Three options`, q:`When members do not comply, what three broad options exist?`, a:`Administrative tools, nonjudicial punishment (Article 15), and judicial punishment (courts-martial).` },
  { module:`Military Justice`, ref:`Admin objectives`, q:`Name the three objectives of administrative action.`, a:`1) To reform the offender 2) To deter others from similar actions 3) To maintain consistent, effective group standards.` },
  { module:`Military Justice`, ref:`Letters`, q:`Distinguish LOC, LOA, and LOR.`, a:`Letter of Counseling (LOC) documents verbal counseling for minor infractions. Letter of Admonishment (LOA) is more severe than an LOC, for more serious infractions. Letter of Reprimand (LOR) is an official censure and the most severe of the three.` },
  { module:`Military Justice`, ref:`UIF`, q:`What is an Unfavorable Information File (UIF)?`, a:`An official record of unfavorable information about a member's conduct and performance. Some items are mandatory filings, such as Article 15s, court-martial convictions, and officer LORs.` },
  { module:`Military Justice`, ref:`Control Roster`, q:`What is the Control Roster?`, a:`Establishes a 6-month observation and rehabilitation period. It is NOT a punishment, but it affects eligibility for reenlistment, promotion, and PCS. See DAFI 36-2907.` },
  { module:`Military Justice`, ref:`OSR`, q:`What is the Officer Selection Record (OSR)?`, a:`The documents used by promotion boards to evaluate officers for promotion.` },
  { module:`Military Justice`, ref:`NJP`, q:`Explain nonjudicial punishment.`, a:`Authorized by Article 15, UCMJ — punishment not imposed by a court of justice. Used for minor offenses; more serious than an LOC, LOA, or LOR, but NOT a criminal conviction. Its purpose is to maintain morale, discipline, and efficiency and to correct or rehabilitate the offender.` },
  { module:`Military Justice`, ref:`NJP authority`, q:`Who imposes an Article 15?`, a:`The commander. Other officers or NCOs may recommend it, but only the commander imposes it.` },
  { module:`Military Justice`, ref:`NJP rights`, q:`What are a member's rights regarding an Article 15?`, a:`The member may demand trial by court-martial in lieu of accepting the Article 15, and may consult the Area Defense Counsel before deciding.` },
  { module:`Military Justice`, ref:`Summary CM`, q:`Summary Court-Martial (SCM).`, a:`Tries minor offenses, ENLISTED ONLY. Normally one officer. The accused may refuse and demand a special court-martial.` },
  { module:`Military Justice`, ref:`Special CM`, q:`Special Court-Martial (SPCM).`, a:`Tries intermediate offenses. DAF policy provides a military judge on every special court-martial.` },
  { module:`Military Justice`, ref:`General CM`, q:`General Court-Martial (GCM).`, a:`Tries the most serious offenses, with the possibility of maximum punishment.` },
  { module:`Military Justice`, ref:`SJA`, q:`Function of the Staff Judge Advocate (SJA).`, a:`The commander's legal staff; represents the Air Force and Space Force in all legal matters; advises commanders on military justice, investigations, searches and seizures, and disciplinary actions; and manages the installation legal office covering military justice, claims, and civil law.` },
  { module:`Military Justice`, ref:`ADC`, q:`Function of the Area Defense Counsel (ADC).`, a:`Represents Air Force and Space Force personnel accused of wrongdoing, of ALL ranks. Operates through a separate chain of command to ensure independence. Provides advice and representation for criminal investigations, LORs, Article 15s, administrative actions, and courts-martial.` },
  { module:`Military Justice`, ref:`VC`, q:`Function of the Victims' Counsel (VC).`, a:`Advises and represents victims of alleged sexual assault and domestic violence; assists victims with their rights and can represent them in certain matters during courts-martial; and operates through a separate chain of command from the SJA.` },
];

